INSERT INTO membrane_retrofits(assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES
('RT073-01','MR073-01','CN0327','west_shared_existing','conditional_screen',1,'分股回用及减量','低氟或末端出水预处理后UF/RO试验；高氟高盐支路另作NF/ED选择性和蒸发减量试验','conditional','氟盐结垢、有机物及浓液处置','现状500t/d生化、269t/d约值、2024总排口监测','不把全厂能力或总排口水质当膜进水；不假定已有蒸发余量','实际分股流量、离子、COD/AOX、蒸发余量、吨水成本、回用需求','分股采样、预处理与膜连续小试、浓水平衡及全成本比较','现有除氟生化纳管、非膜优化',2,2,NULL,NULL,NULL,NULL,'氟盐及预处理风险有来源；其余未知，综合难度unknown','2026-11-28');
INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N073-01','CN0327','S073-01','共享站扩建后状态','3.8.3.1','后续报告明确500t/d生化已建、实际约269t/d；415.44t/d为批准废水。2024在线监测不证明当月500t/d已建。原图删节，截图超时，文本可读。2022–23总排口旧指标未重复录入。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N073-02','CN0328','S073-01','东区状态变化','4.1.1 p81','4000t/a含氟精细化学品（非催化剂产能）扩建方案拟拆东区催化剂配置车间建甲类罐区。旧100t/a催化剂历史保留，不认定拆除或停产已发生；待验收和许可变更。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N073-03','CN0327','S073-01','残余物设计及共用口径','3.8.3.3 S01-30至S04-30，S01/04/08-31','催化剂和聚合物混合项目达产预测：废碱液7.312t/a、蒸发废渣6.8t/a、球磨废料6.828t/a、压滤废树脂3.1t/a；公辅污泥181t/a、污水废渣235t/a、预处理废盐581.2t/a。非实际产生量、非纯催化剂流股；不作实际费用。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
