PRAGMA foreign_keys=ON;
BEGIN;
-- Preserve exact-track dispatch; expose document review history across gap/scope changes.
CREATE VIEW v_research_document_tracks AS
SELECT r.*,s.name,z.title,z.url,q.next_gap,q.public_disposition,
CASE WHEN r.state='wrong_scope' THEN 'exclude_this_scope'
WHEN r.state='section_done' THEN 'section_done'
WHEN r.state='blocked' AND (r.next_check_on IS NULL OR r.next_check_on>date('now','+8 hours')) THEN 'recovery_cooldown'
WHEN r.state='blocked' THEN 'recover_new_path'
WHEN r.state='partial' THEN 'extract_remaining_section'
ELSE 'verify_scope_and_access' END AS track_action
FROM research_document_review r JOIN sites s USING(site_id) JOIN sources z USING(source_id)
LEFT JOIN v_public_research_queue q USING(site_id);
DROP VIEW v_research_document_dispatch;
CREATE VIEW v_research_document_dispatch AS
SELECT d.*,r.state,r.locator,r.remaining_work,r.reviewed_on,r.next_check_on,
CASE WHEN r.state='wrong_scope' THEN 'exclude_this_scope'
WHEN r.state='section_done' THEN 'section_done'
WHEN r.state='blocked' AND (r.next_check_on IS NULL OR r.next_check_on>date('now','+8 hours')) THEN 'recovery_cooldown'
WHEN r.state='blocked' THEN 'recover_new_path'
WHEN r.state='partial' THEN 'extract_remaining_section'
WHEN EXISTS(SELECT 1 FROM research_document_review h WHERE h.site_id=d.site_id AND h.source_id=d.source_id) THEN 'review_prior_tracks_before_new_gap'
ELSE 'verify_scope_and_access' END AS document_action,
(SELECT count(*) FROM research_document_review h WHERE h.site_id=d.site_id AND h.source_id=d.source_id) AS prior_track_count
FROM v_document_backlog_candidates d
LEFT JOIN research_document_review r ON r.site_id=d.site_id AND r.source_id=d.source_id AND r.scope_key='site_current' AND r.gap=d.next_gap;
CREATE VIEW v_research_dispatch_audit AS
SELECT 'site_dispatch' AS kind,dispatch_action AS status,count(*) AS n FROM v_research_dispatch GROUP BY 2
UNION ALL SELECT 'attempt_track',revisit_status,count(*) FROM v_research_revisit_due GROUP BY 2
UNION ALL SELECT 'document_candidate',document_action,count(*) FROM v_research_document_dispatch GROUP BY 2
UNION ALL SELECT 'document_track',track_action,count(*) FROM v_research_document_tracks GROUP BY 2
UNION ALL SELECT 'attempt_outcome',outcome,count(*) FROM research_revisit_attempts GROUP BY 2
UNION ALL SELECT 'event',CASE WHEN consumed_by_attempt IS NULL THEN 'pending' ELSE 'consumed' END,count(*) FROM research_reopen_events GROUP BY 2;

