UPDATE sites SET water_summary='后续环评现状500t/d已建生化站、约269t/d实际处理；2024历史监测；现行膜/成本未知' WHERE site_id='CN0327';
UPDATE sites SET status='历史制造；2025扩建方案拟拆催化剂配置车间，实际停产/拆除待核' WHERE site_id='CN0328';
